@import url('https://fonts.googleapis.com/css2?family=DM+Mono:wght@400;500&family=DM+Sans:wght@400;500;600;700;800&family=Space+Grotesk:wght@400;500;600;700&display=swap');
:root{--ink:#10131e;--ink-2:#171b28;--panel:#1b2030;--paper:#f0ede5;--muted:#9297a7;--pink:#ff5575;--pink-soft:#ff8094;--teal:#78d5c9;--line:rgba(242,240,234,.13);--mono:'DM Mono',monospace;--display:'Space Grotesk',sans-serif;--body:'DM Sans',sans-serif}
*{box-sizing:border-box}html,body{margin:0;min-height:100%;background:var(--ink);color:var(--paper);font-family:var(--body)}body{min-height:100vh;overflow-x:hidden}.app-shell{position:relative;min-height:100vh;max-width:1600px;margin:0 auto;padding:0 6.1vw;overflow:hidden;background:radial-gradient(ellipse at 75% 40%,rgba(46,45,68,.22),transparent 42%),var(--ink)}.ambient{position:absolute;pointer-events:none;border-radius:50%;filter:blur(100px);opacity:.11}.ambient-one{width:360px;height:360px;background:#ff3768;top:15%;right:4%}.ambient-two{width:280px;height:280px;background:#6257bf;bottom:5%;left:17%}.topbar{height:82px;position:relative;z-index:3;display:flex;align-items:center;border-bottom:1px solid var(--line);gap:30px}.wordmark{display:flex;align-items:center;gap:10px;color:var(--paper);font:700 13px var(--display);letter-spacing:.11em;text-decoration:none}.mark{width:28px;height:28px;display:grid;place-items:center;border:1px solid var(--pink);color:var(--pink);font:500 10px var(--mono);letter-spacing:-.08em;transform:rotate(-5deg)}.wordmark-light{font-weight:400;color:#aaaebb}.top-meta{margin-left:auto;display:flex;align-items:center;gap:17px;color:#9196a6;font:10px var(--mono);letter-spacing:.12em}.chapter-tag{color:var(--pink-soft)}.top-divider{height:13px;width:1px;background:var(--line)}.top-actions{display:flex;gap:8px}.icon-button{border:1px solid var(--line);background:transparent;color:var(--paper);height:34px;min-width:36px;padding:0 10px;cursor:pointer;font:16px var(--body);transition:.2s}.icon-button:hover{border-color:var(--pink);color:var(--pink)}.sound-label{font:9px var(--mono);letter-spacing:.08em;margin-left:7px}.menu-button{font-size:13px}.title-screen{position:relative;min-height:min(760px,calc(100vh - 142px));display:flex;align-items:center;padding:35px 0 55px}.title-copy{position:relative;z-index:2;width:47%;padding:0 0 0 3.7%}.eyebrow{display:flex;align-items:center;gap:12px;color:#b1b5c2;font:10px var(--mono);letter-spacing:.19em;margin:0 0 26px}.eyebrow-line{width:32px;height:1px;background:var(--pink)}h1{font:700 clamp(80px,11vw,156px)/.72 var(--display);letter-spacing:-.105em;margin:0 0 30px;color:var(--paper)}h1 em{font-style:normal;color:var(--pink);letter-spacing:-.105em}.title-subtitle{font:500 23px/1.26 var(--display);letter-spacing:-.035em;margin:0 0 18px}.title-subtitle strong{color:var(--teal);font-weight:500}.title-description{color:#a0a5b3;font-size:13px;line-height:1.75;letter-spacing:.02em;margin:0 0 30px}.primary-button{display:flex;align-items:center;justify-content:space-between;gap:38px;min-width:215px;padding:15px 16px 15px 19px;border:0;background:var(--pink);color:#191824;font:700 10px var(--mono);letter-spacing:.1em;cursor:pointer;transition:transform .2s,background .2s}.primary-button:hover{background:#ff7890;transform:translateY(-2px)}.button-arrow{font-size:17px}.title-foot{display:flex;align-items:center;gap:10px;color:#7e8494;font:9px var(--mono);letter-spacing:.06em;margin-top:30px}.foot-dot{width:3px;height:3px;background:var(--pink);border-radius:50%}.title-art{position:absolute;right:5%;top:50%;transform:translateY(-49%);width:48%;height:520px;max-height:70vh;min-height:400px}.orbit{position:absolute;border:1px solid rgba(230,225,230,.12);border-radius:50%;transform:rotate(-30deg)}.orbit-a{width:85%;height:55%;top:22%;left:6%}.orbit-b{width:88%;height:66%;top:13%;left:2%;transform:rotate(53deg);border-color:rgba(255,85,117,.18)}.tower-shadow{position:absolute;bottom:5%;left:15%;height:18%;width:70%;background:#000;filter:blur(40px);opacity:.65}.tower{position:absolute;left:36%;top:12%;width:29%;height:77%;background:linear-gradient(90deg,#28283b,#36354c 48%,#242437);clip-path:polygon(13% 20%,50% 0,87% 20%,87% 100%,13% 100%);filter:drop-shadow(0 15px 30px rgba(0,0,0,.4))}.tower:before{content:'';position:absolute;left:45%;top:17%;width:10%;height:83%;background:rgba(255,255,255,.035)}.tower-roof{position:absolute;top:6%;left:31%;width:38%;height:26%;background:#41405a;clip-path:polygon(50% 0,100% 100%,0 100%)}.tower-window{position:absolute;top:26%;left:42%;width:16%;height:17%;border:2px solid #8a5368;border-radius:50% 50% 4px 4px;background:#171728;box-shadow:0 0 22px rgba(255,85,117,.5)}.tower-window span{position:absolute;left:46%;top:0;width:2px;height:100%;background:#a96173}.tower-clock{position:absolute;top:51%;left:22%;width:56%;text-align:center;padding:11px 0;color:#ffb1b8;border:1px solid rgba(255,133,145,.55);background:#201c2b;font:13px var(--mono);letter-spacing:.06em;box-shadow:0 0 28px rgba(255,85,117,.16)}.tower-clock span{color:var(--pink)}.tower-base{position:absolute;bottom:0;left:0;width:100%;height:8%;background:#41405a}.bell-shape{position:absolute;z-index:1;top:27%;left:24%;width:14%;height:15%;background:linear-gradient(120deg,#c59b72,#705940);clip-path:polygon(44% 0,57% 0,62% 24%,87% 63%,96% 87%,4% 87%,13% 63%,38% 24%);filter:drop-shadow(0 0 16px rgba(255,190,117,.4));transform:rotate(-12deg)}.bell-shape:after{content:'';position:absolute;left:43%;bottom:0;width:14%;height:19%;border-radius:50%;background:#d7ad79}.art-label{position:absolute;color:#a6a4b2;font:9px/1.5 var(--mono);letter-spacing:.13em}.label-left{left:6%;top:33%}.label-right{right:7%;top:23%;text-align:right;color:#707585}.art-stamp{position:absolute;right:10%;bottom:13%;color:var(--pink);font:10px/1.4 var(--mono);letter-spacing:.17em;transform:rotate(8deg);border:1px solid rgba(255,85,117,.55);padding:10px}.art-stamp b{font-size:15px}.art-index{position:absolute;left:10%;bottom:9%;color:#777d8d;font:9px var(--mono);letter-spacing:.08em}.title-bottom{position:absolute;bottom:20px;left:0;right:0;display:flex;justify-content:space-between;color:#626879;font:9px var(--mono);letter-spacing:.09em}.site-footer{position:relative;z-index:1;height:60px;border-top:1px solid var(--line);display:flex;align-items:center;justify-content:space-between;color:#727888;font:9px var(--mono);letter-spacing:.08em}.site-footer b{color:var(--pink);padding:0 5px}
.hidden{display:none!important}
.game-screen{position:relative;min-height:calc(100vh - 143px);padding:29px 0 32px}.game-layout{max-width:1240px;min-height:570px;height:min(70vh,720px);margin:0 auto;display:grid;grid-template-columns:220px 1fr;border:1px solid var(--line);background:rgba(20,23,35,.76);box-shadow:0 24px 70px rgba(0,0,0,.2)}.left-rail{position:relative;padding:32px 24px 25px;border-right:1px solid var(--line);background:rgba(255,255,255,.018)}.rail-label{display:flex;justify-content:space-between;font:10px var(--mono);letter-spacing:.12em;color:#a8adba}.rail-label span{color:var(--pink)}.rail-rule{height:1px;background:var(--line);margin:16px 0 21px}.case-title{font:700 25px/.98 var(--display);letter-spacing:-.05em}.case-title em{font-style:normal;color:var(--pink)}.case-status{margin-top:24px;color:var(--teal);font:9px var(--mono);letter-spacing:.12em}.case-status i{display:inline-block;width:6px;height:6px;border-radius:50%;background:var(--teal);margin-right:7px;box-shadow:0 0 10px var(--teal)}.rail-progress{height:3px;background:#303342;margin-top:10px}.rail-progress span{display:block;width:0;height:100%;background:var(--pink);transition:width .5s}.progress-caption{display:flex;justify-content:space-between;margin-top:8px;color:#747b8a;font:8px var(--mono);letter-spacing:.08em}.progress-caption b{color:#c7c6ce;font-weight:400}.rail-bottom{position:absolute;left:24px;right:24px;bottom:25px;padding-top:13px;border-top:1px solid var(--line);display:flex;flex-direction:column;gap:7px;color:#727888;font:8px var(--mono);letter-spacing:.1em}.rail-bottom b{font-size:10px;color:#bbb8c5;font-weight:400}.play-area{position:relative;min-width:0;overflow:hidden}.story-view{height:100%;min-height:570px;display:flex;flex-direction:column;position:relative;background:radial-gradient(ellipse at 65% 35%,rgba(69,57,79,.2),transparent 42%)}.scene-heading{display:flex;align-items:center;gap:12px;padding:26px 30px 0;color:#898e9f;font:9px var(--mono);letter-spacing:.15em}.scene-heading:before{content:'';width:18px;height:1px;background:var(--pink)}.scene-heading .location{color:#d2ced6}.story-stage{position:relative;flex:1;min-height:280px;display:flex;align-items:center;justify-content:center;overflow:hidden}.stage-grid{position:absolute;inset:10% 12%;opacity:.14;background-image:linear-gradient(rgba(220,220,230,.12) 1px,transparent 1px),linear-gradient(90deg,rgba(220,220,230,.12) 1px,transparent 1px);background-size:35px 35px;mask-image:radial-gradient(ellipse,black,transparent 72%)}.stage-halo{position:absolute;width:270px;height:270px;border:1px solid rgba(255,85,117,.19);border-radius:50%;box-shadow:0 0 80px rgba(255,85,117,.08),inset 0 0 60px rgba(255,85,117,.04)}.stage-halo:before,.stage-halo:after{content:'';position:absolute;inset:20px;border:1px solid rgba(220,220,230,.07);border-radius:50%}.stage-halo:after{inset:-22px;border-style:dashed;opacity:.5}.character{--character:#f56d82;position:relative;z-index:1;display:flex;align-items:center;justify-content:center;width:174px;height:230px;filter:drop-shadow(0 16px 22px rgba(0,0,0,.3));animation:floatIn .4s ease both}.character .coat{position:absolute;bottom:0;width:166px;height:112px;background:linear-gradient(115deg,#27293b,var(--character));clip-path:polygon(22% 0,41% 12%,59% 12%,78% 0,100% 25%,86% 100%,14% 100%,0 25%);border-top:2px solid rgba(255,255,255,.22)}.character .neck{position:absolute;top:105px;width:30px;height:36px;background:#d5a28f}.character .head{position:absolute;top:30px;width:103px;height:111px;border-radius:48% 48% 43% 43%;background:linear-gradient(135deg,#f2c0a6,#c88e7e);box-shadow:inset -12px -5px 0 rgba(87,47,63,.1)}.character .hair{position:absolute;top:21px;width:116px;height:76px;border-radius:55% 48% 17% 22%;background:var(--character);z-index:2;clip-path:polygon(4% 39%,15% 11%,34% 1%,57% 10%,87% 0,100% 42%,87% 61%,81% 100%,68% 63%,49% 84%,38% 61%,18% 100%,13% 60%,0 68%)}.character .fringe{position:absolute;z-index:3;top:70px;left:38px;width:67px;height:29px;background:var(--character);clip-path:polygon(0 0,100% 0,78% 100%,56% 48%,38% 100%,25% 38%,12% 100%)}.character .eye{position:absolute;top:87px;width:6px;height:8px;border-radius:50%;background:#292335;z-index:4}.character .eye.left{left:68px}.character .eye.right{right:68px}.character .mouth{position:absolute;top:113px;width:13px;height:5px;border-bottom:1px solid #8a4d54;border-radius:50%;z-index:4}.character .badge{position:absolute;z-index:5;bottom:31px;right:29px;width:20px;height:20px;border-radius:50%;border:1px solid rgba(255,255,255,.6);background:#22283a;color:#fff;text-align:center;padding-top:4px;font:7px var(--mono)}.character.tone-teal{--character:#42a79f}.character.tone-gold{--character:#d89d4c}.character.tone-violet{--character:#9276c6}.character.tone-blue{--character:#588ac2}.character.tone-dark{--character:#4c5066}.character.tone-rose{--character:#d05a7a}.stage-caption{position:absolute;bottom:15px;left:50%;transform:translateX(-50%);white-space:nowrap;color:#707686;font:8px var(--mono);letter-spacing:.12em}.dialogue-box{position:relative;z-index:2;margin:0 26px 25px;padding:19px 22px 18px;border:1px solid rgba(239,235,230,.16);background:rgba(25,28,42,.96);box-shadow:0 15px 35px rgba(0,0,0,.2);min-height:136px}.speaker-line{display:flex;align-items:center;gap:9px;margin-bottom:12px}.speaker-name{color:var(--pink-soft);font:600 10px var(--mono);letter-spacing:.14em;text-transform:uppercase}.speaker-role{color:#7b8191;font:9px var(--mono);letter-spacing:.06em}.dialogue-text{max-width:780px;color:#e3e0e0;font-size:14px;line-height:1.65;min-height:47px}.dialogue-footer{display:flex;justify-content:space-between;align-items:center;margin-top:12px}.dialogue-hint{color:#717787;font:8px var(--mono);letter-spacing:.08em}.next-button{border:0;background:transparent;color:var(--teal);padding:6px 0 6px 14px;cursor:pointer;font:10px var(--mono);letter-spacing:.1em}.next-button:hover{color:white}.next-button span{font-size:15px;margin-left:10px}.choice-list{display:flex;gap:8px;flex-wrap:wrap;margin-top:13px}.choice-button{flex:1;min-width:150px;padding:11px 12px;border:1px solid var(--line);background:rgba(255,255,255,.03);color:#d9d8df;text-align:left;font:11px var(--body);cursor:pointer;transition:.18s}.choice-button:hover{border-color:var(--pink);background:rgba(255,85,117,.09)}

/* investigation */
.investigation-view{height:100%;min-height:570px;padding:27px 30px 28px;display:flex;flex-direction:column;background:radial-gradient(ellipse at 70% 8%,rgba(55,75,91,.18),transparent 40%)}.view-kicker{display:flex;justify-content:space-between;align-items:center;color:#8f95a4;font:9px var(--mono);letter-spacing:.13em}.view-kicker b{color:var(--pink);font-weight:400}.view-title{font:600 29px/1.1 var(--display);letter-spacing:-.05em;margin:19px 0 7px}.view-intro{max-width:680px;color:#a5a9b5;font-size:12px;line-height:1.55;margin:0 0 19px}.location-grid{flex:1;display:grid;grid-template-columns:repeat(2,minmax(0,1fr));grid-template-rows:repeat(2,minmax(135px,1fr));gap:10px;min-height:300px}.location-card{position:relative;overflow:hidden;text-align:left;padding:14px;border:1px solid var(--line);background:linear-gradient(140deg,rgba(42,48,66,.85),rgba(25,28,41,.85));color:var(--paper);cursor:pointer;transition:transform .2s,border .2s}.location-card:hover{transform:translateY(-2px);border-color:rgba(255,85,117,.7)}.location-card:before{content:'';position:absolute;inset:0;background:linear-gradient(125deg,transparent 35%,rgba(255,255,255,.025) 35.2%,transparent 35.8%);pointer-events:none}.location-card.visited{border-color:rgba(120,213,201,.45)}.location-art{position:absolute;right:13px;top:15px;width:62px;height:53px;opacity:.7}.location-art:before,.location-art:after{content:'';position:absolute}.art-booth:before{left:10px;top:0;width:38px;height:52px;border:1px solid #d56a80;background:linear-gradient(90deg,transparent 45%,rgba(255,85,117,.22) 46%,transparent 53%)}.art-booth:after{left:20px;top:11px;width:18px;height:18px;border:1px solid #d56a80;border-radius:50%;box-shadow:0 0 17px rgba(255,85,117,.3)}.art-library:before{left:2px;top:8px;width:57px;height:43px;background:repeating-linear-gradient(90deg,#777497 0 7px,transparent 7px 11px);border-bottom:2px solid #a68ca5}.art-library:after{left:2px;top:0;width:57px;height:7px;background:#a68ca5}.art-gallery:before{left:10px;top:2px;width:42px;height:43px;border:1px solid #8e9da4;box-shadow:inset 0 0 0 5px rgba(120,213,201,.08)}.art-gallery:after{left:27px;top:3px;height:41px;width:1px;background:#8e9da4;box-shadow:-16px 18px 0 -0.5px #8e9da4,16px -10px 0 -0.5px #8e9da4}.art-control:before{left:5px;top:6px;width:52px;height:37px;border:1px solid #ba9a5d;background:repeating-linear-gradient(0deg,transparent 0 7px,rgba(216,157,76,.25) 8px 9px)}.art-control:after{left:15px;top:16px;width:7px;height:7px;border-radius:50%;background:#ff6176;box-shadow:16px 2px 0 #75d7c8,32px -3px 0 #d9b469}.location-name{position:absolute;left:15px;bottom:32px;font:600 15px var(--display);letter-spacing:-.02em}.location-desc{position:absolute;left:15px;bottom:14px;color:#8d93a3;font:8px var(--mono);letter-spacing:.09em}.location-index{position:absolute;top:13px;left:15px;color:#7a8090;font:8px var(--mono)}.clue-stamp{position:absolute;right:13px;bottom:13px;color:var(--teal);font:8px var(--mono);letter-spacing:.07em}.clue-stamp:before{content:'✓';margin-right:5px}.investigation-bottom{display:flex;justify-content:space-between;align-items:center;margin-top:14px;color:#828898;font:9px var(--mono);letter-spacing:.07em}.evidence-count{color:#c4c6ce}.evidence-count b{color:var(--teal);font-weight:400}.trial-button{background:var(--pink);border:0;color:#171824;padding:11px 15px;font:700 9px var(--mono);letter-spacing:.1em;cursor:pointer;transition:.2s}.trial-button:disabled{background:#393b4a;color:#828694;cursor:not-allowed}.trial-button:not(:disabled):hover{background:#ff8094;transform:translateY(-1px)}
.location-detail{height:100%;min-height:570px;padding:30px;display:flex;flex-direction:column;background:radial-gradient(ellipse at 75% 35%,rgba(64,57,79,.2),transparent 45%)}.back-button{align-self:flex-start;border:0;background:transparent;color:#9da2ae;padding:0;cursor:pointer;font:9px var(--mono);letter-spacing:.1em}.back-button:hover{color:var(--teal)}.detail-scene{position:relative;min-height:190px;flex:1;margin:18px 0;background:linear-gradient(145deg,rgba(43,48,64,.55),rgba(20,22,34,.5));border:1px solid var(--line);overflow:hidden}.detail-scene:before{content:'';position:absolute;inset:20px;border:1px solid rgba(255,255,255,.08)}.detail-scene:after{content:'';position:absolute;left:50%;top:50%;width:180px;height:1px;background:rgba(255,255,255,.1);transform:translate(-50%,-50%);box-shadow:0 0 0 45px transparent}.scene-symbol{position:absolute;left:50%;top:50%;transform:translate(-50%,-50%);display:grid;place-items:center;width:108px;height:108px;border:1px solid rgba(255,85,117,.55);border-radius:50%;color:var(--pink);font:30px var(--mono);box-shadow:0 0 40px rgba(255,85,117,.1)}.scene-symbol.teal{border-color:rgba(120,213,201,.5);color:var(--teal)}.scene-symbol.gold{border-color:rgba(216,157,76,.5);color:#d8aa61}.detail-heading{font:600 25px var(--display);letter-spacing:-.04em;margin:0 0 8px}.detail-text{max-width:650px;color:#b1b5c0;font-size:13px;line-height:1.7;margin:0 0 18px}.found-clue{padding:12px 14px;border-left:2px solid var(--teal);background:rgba(120,213,201,.07);color:#bce5de;font-size:12px;line-height:1.5;margin:0 0 17px}.found-clue b{display:block;color:var(--teal);font:9px var(--mono);letter-spacing:.12em;margin-bottom:4px}.detail-action{align-self:flex-end}.detail-action[disabled]{background:#343849;color:#a2a4ad;cursor:default}
/* class trial */
.trial-view{height:100%;min-height:570px;padding:25px 28px 22px;display:flex;flex-direction:column;background:radial-gradient(ellipse at 50% 12%,rgba(139,42,72,.19),transparent 48%)}.trial-top{display:flex;justify-content:space-between;align-items:center;color:#9298a8;font:9px var(--mono);letter-spacing:.12em}.trial-top b{color:var(--pink);font-weight:400}.trial-title{margin:17px 0 5px;font:700 28px var(--display);letter-spacing:-.05em}.trial-prompt{color:#b6b8c2;font-size:12px;line-height:1.55;margin:0 0 15px;max-width:690px}.trial-person{display:flex;align-items:center;gap:12px;padding:11px 13px;background:rgba(255,255,255,.035);border:1px solid var(--line);margin-bottom:13px}.mini-avatar{width:37px;height:37px;border-radius:50%;display:grid;place-items:center;background:var(--pink);color:#171824;font:600 12px var(--display)}.trial-person-name{font:600 11px var(--mono);letter-spacing:.08em}.trial-person-role{display:block;color:#808696;font:8px var(--mono);margin-top:4px}.trial-person-quote{margin-left:auto;max-width:52%;text-align:right;color:#c5c4cc;font-size:11px;line-height:1.45;font-style:italic}.evidence-label{display:flex;align-items:center;gap:9px;color:#8c91a0;font:8px var(--mono);letter-spacing:.13em;margin-bottom:8px}.evidence-label:after{content:'';height:1px;flex:1;background:var(--line)}.evidence-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:7px;flex:1;min-height:150px}.evidence-card{position:relative;padding:11px 12px 10px 37px;border:1px solid var(--line);background:rgba(255,255,255,.025);color:#d7d6de;text-align:left;cursor:pointer;font:11px var(--body);transition:.18s}.evidence-card:before{content:attr(data-index);position:absolute;left:11px;top:12px;color:var(--pink);font:9px var(--mono)}.evidence-card small{display:block;color:#7e8494;font:8px var(--mono);letter-spacing:.04em;margin-top:5px}.evidence-card:hover,.evidence-card.selected{border-color:var(--pink);background:rgba(255,85,117,.09)}.trial-feedback{min-height:32px;margin-top:10px;padding:8px 11px;color:#999eac;font-size:10px;line-height:1.45;border-left:2px solid #626878;background:rgba(255,255,255,.025)}.trial-feedback.good{color:#b8e4d7;border-color:var(--teal);background:rgba(120,213,201,.07)}.trial-feedback.bad{color:#ffc0c7;border-color:var(--pink);background:rgba(255,85,117,.07)}.trial-bottom{display:flex;align-items:center;justify-content:space-between;margin-top:10px}.trial-dots{display:flex;gap:5px}.trial-dots i{width:16px;height:3px;background:#434654}.trial-dots i.done{background:var(--teal)}.trial-dots i.current{background:var(--pink)}.submit-button{border:0;background:var(--pink);color:#171824;padding:10px 16px;font:700 9px var(--mono);letter-spacing:.1em;cursor:pointer}.submit-button:hover{background:#ff8296}.submit-button:disabled{background:#373a49;color:#8a8e9c;cursor:not-allowed}
