    playArea.innerHTML = `<div class="trial-view"><div class="trial-top"><span>MERIDIAN INSTITUTE / CLASS TRIAL</span><b>DEBATE ${String(qIndex + 1).padStart(2, '0')} / 04</b></div><h2 class="trial-title">Connect the evidence.</h2><p class="trial-prompt">${q.prompt}</p><div class="trial-person"><span class="mini-avatar">${q.speaker.charAt(0)}</span><span class="trial-person-name">${q.speaker}<small class="trial-person-role">TESTIMONY ON THE STAND</small></span><span class="trial-person-quote">${q.quote}</span></div><div class="evidence-label">SELECT THE STRONGEST CONTRADICTION</div><div class="evidence-grid">${buttons}</div>${feedback}<div class="trial-bottom"><div class="trial-dots">${dots}</div><button class="submit-button" id="submitEvidence" ${app.selected === null || app.trialSolved ? 'disabled' : ''}>${app.trialSolved ? 'EVIDENCE ACCEPTED ✓' : 'PRESENT EVIDENCE →'}</button></div></div>`;
